// Split one CSV line into fields.
export function parseLine(line) {
  return line.split(',').map((field) => field.trim());
}

export function parseInvoices(text) {
  const [header, ...rows] = text.trim().split(/\r?\n/);
  const keys = parseLine(header);
  return rows
    .filter((row) => row.trim() !== '')
    .map((row) => {
      const values = parseLine(row);
      const invoice = Object.fromEntries(keys.map((k, i) => [k, values[i]]));
      invoice.amount = Number(invoice.amount);
      return invoice;
    });
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseLine, parseInvoices } from '../src/csv.js';
import { totalByCustomer } from '../src/totals.js';

test('splits a simple line', () => {
  assert.deepEqual(parseLine('a, b ,c'), ['a', 'b', 'c']);
});

test('keeps commas inside quoted fields', () => {
  assert.deepEqual(parseLine('1,"Acme, Inc.",120.50'), ['1', 'Acme, Inc.', '120.50']);
});

test('unescapes doubled quotes', () => {
  assert.deepEqual(parseLine('2,"The ""Best"" Shop",10'), ['2', 'The "Best" Shop', '10']);
});

test('parses invoices and totals them per customer', () => {
  const csv = 'id,customer,amount\n1,"Acme, Inc.",120.50\n2,Globex,80\n3,"Acme, Inc.",29.50\n';
  const invoices = parseInvoices(csv);
  assert.equal(invoices.length, 3);
  assert.deepEqual(totalByCustomer(invoices), { 'Acme, Inc.': 150, Globex: 80 });
});
{
  "name": "csv-import",
  "version": "0.3.1",
  "type": "module",
  "scripts": { "test": "node --test" }
}

