+  const fields = [];
+  let field = '';
+  let inQuotes = false;
+
+  for (let i = 0; i < line.length; i += 1) {
+    const char = line[i];
+
+    if (char === '"') {
+      if (inQuotes && line[i + 1] === '"') {
+        field += '"';
+        i += 1;
+      } else if (inQuotes) {
+        inQuotes = false;
+      } else if (field.trim() === '') {
+        // A quote starts a quoted field only before any non-whitespace content.
+        field = '';
+        inQuotes = true;
+      } else {
+        field += char;
+      }
+    } else if (char === ',' && !inQuotes) {
+      fields.push(field.trim());
+      field = '';
+    } else {
+      field += char;
+    }
+  }
+
+  fields.push(field.trim());
+  return fields;
 }
